import{_ as t,o as a,c as r,a2 as i}from"./chunks/framework.yJK3qstQ.js";const p=JSON.parse('{"title":"Interview Preparation: 150+ Questions & Answers","description":"","frontmatter":{},"headers":[],"relativePath":"09-interview-qa.md","filePath":"09-interview-qa.md"}'),s={name:"09-interview-qa.md"};function n(o,e,d,l,h,c){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="interview-preparation-150-questions-answers" tabindex="-1">Interview Preparation: 150+ Questions &amp; Answers <a class="header-anchor" href="#interview-preparation-150-questions-answers" aria-label="Permalink to &quot;Interview Preparation: 150+ Questions &amp; Answers&quot;">​</a></h1><h2 id="core-architectural-questions" tabindex="-1">Core Architectural Questions <a class="header-anchor" href="#core-architectural-questions" aria-label="Permalink to &quot;Core Architectural Questions&quot;">​</a></h2><h3 id="q1-can-you-walk-me-through-the-architecture-of-the-gesture-pdf-presenter" tabindex="-1">Q1: Can you walk me through the architecture of the Gesture PDF Presenter? <a class="header-anchor" href="#q1-can-you-walk-me-through-the-architecture-of-the-gesture-pdf-presenter" aria-label="Permalink to &quot;Q1: Can you walk me through the architecture of the Gesture PDF Presenter?&quot;">​</a></h3><p><strong>Answer</strong>: Gesture PDF Presenter is a touchless presentation control system built with React 18, TypeScript, and Node.js. It captures standard webcam video via <code>react-webcam</code> and processes frames through Google&#39;s MediaPipe Hands WebAssembly pipeline at 30 frames per second. The pipeline extracts 21 three-dimensional hand landmarks per frame, passing them to our geometric gesture engine in <code>GestureControl.tsx</code>. The engine classifies mid-air gestures—such as lateral swipes for page transitions, index finger extension for virtual laser pointing, and pinch gestures for zooming—dispatching events to a PDF.js canvas renderer that displays vectorized slides.</p><h3 id="q2-how-do-you-prevent-accidental-slide-flips-when-a-speaker-naturally-gestures-while-talking" tabindex="-1">Q2: How do you prevent accidental slide flips when a speaker naturally gestures while talking? <a class="header-anchor" href="#q2-how-do-you-prevent-accidental-slide-flips-when-a-speaker-naturally-gestures-while-talking" aria-label="Permalink to &quot;Q2: How do you prevent accidental slide flips when a speaker naturally gestures while talking?&quot;">​</a></h3><p><strong>Answer</strong>: In <code>services/gestures.ts</code>, we implement a two-stage filter. First, we track the lateral velocity of the wrist landmark ($dx/dt$) over five consecutive frames; a slide change is only registered if velocity exceeds 400 pixels per second. Second, once a swipe is recognized, the system locks into a 500-millisecond refractory debounce window, ignoring all motion until the presenter stabilizes their hand.</p><h3 id="q3-why-did-you-run-mediapipe-client-side-rather-than-streaming-video-to-a-server" tabindex="-1">Q3: Why did you run MediaPipe client-side rather than streaming video to a server? <a class="header-anchor" href="#q3-why-did-you-run-mediapipe-client-side-rather-than-streaming-video-to-a-server" aria-label="Permalink to &quot;Q3: Why did you run MediaPipe client-side rather than streaming video to a server?&quot;">​</a></h3><p><strong>Answer</strong>: Streaming 30fps 720p video to a server creates massive network bandwidth consumption and introduces 150-300ms of latency, which destroys the responsive feel of a laser pointer. By running MediaPipe&#39;s WebAssembly and WebGL models directly on the client&#39;s laptop, landmark tracking executes with sub-18ms latency with zero bandwidth consumption and complete camera privacy.</p><h3 id="q4-how-does-the-virtual-laser-pointer-work-mathematically" tabindex="-1">Q4: How does the virtual laser pointer work mathematically? <a class="header-anchor" href="#q4-how-does-the-virtual-laser-pointer-work-mathematically" aria-label="Permalink to &quot;Q4: How does the virtual laser pointer work mathematically?&quot;">​</a></h3><p><strong>Answer</strong>: When our classifier detects an extended index finger while the other three fingers remain curled toward the palm, it enters laser pointer mode. It takes the normalized ${x, y}$ coordinates of Landmark 8 (index fingertip), scales them to the slide canvas dimensions, and draws a glowing circular radial gradient on an overlaid HTML5 canvas with sub-pixel interpolation.</p><h3 id="q5-how-do-you-ensure-high-dpi-crispness-when-rendering-pdfs" tabindex="-1">Q5: How do you ensure high-DPI crispness when rendering PDFs? <a class="header-anchor" href="#q5-how-do-you-ensure-high-dpi-crispness-when-rendering-pdfs" aria-label="Permalink to &quot;Q5: How do you ensure high-DPI crispness when rendering PDFs?&quot;">​</a></h3><p><strong>Answer</strong>: We query the browser&#39;s <code>window.devicePixelRatio</code> (often 2x on Retina displays). In <code>usePDFViewer.ts</code>, we scale the canvas width and height by this ratio while setting its CSS style width and height to the logical display size, ensuring crisp, unblurred rendering of dense vector diagrams and small fonts.</p>',12)])])}const w=t(s,[["render",n]]);export{p as __pageData,w as default};
